FUNCTION_BLOCK FB
VAR_INPUT
    mode            : INT;          // 0=手动 1=自动 2=串级
    resetBtn        : BOOL;         // 复位上升沿
    scanSeconds     : REAL;         // 本次扫描周期(秒)
    tempSP          : REAL;         // 温度设定值(℃)
    tempPV          : REAL;         // 温度测量值(℃)
    flowPV          : REAL;         // 流量测量值(t/h)
    manualFlowSP    : REAL;         // 手动流量设定值(t/h)
    manualValve     : REAL;         // 手动阀门开度(%)
END_VAR
VAR_OUTPUT
    flowSP          : REAL;         // 流量设定值(t/h, 限幅0..50)
    valveCommand    : REAL;         // 阀门开度指令(%, 限幅0..100)
    fault           : BOOL;         // 故障标志
    normalMode      : BOOL;         // 正常运算拍
END_VAR
VAR
    prevResetBtn        : BOOL := FALSE;
    prevMode            : INT := 16;    // 16与0/1/2都不等，标记首次
    prevFlowSP          : REAL := 0.0;
    prevValveCommand    : REAL := 0.0;
    accT                : REAL := 0.0;  // 外环积分累加器(t/h)
    accF                : REAL := 0.0;  // 内环积分累加器(%)
    isFirstScan         : BOOL := TRUE;
END_VAR

VAR_TEMP
    eT              : REAL;
    eF              : REAL;
    trialT          : REAL;
    trialF          : REAL;
    resetRising     : BOOL;
    modeChanged     : BOOL;
    isFaultCondition: BOOL;
END_VAR

eT := tempSP - tempPV;

resetRising := resetBtn AND NOT prevResetBtn;
modeChanged := (prevMode <> 16) AND (mode <> prevMode);
isFaultCondition := (mode < 0) OR (mode > 2) OR (scanSeconds <= 0.0) OR (scanSeconds > 10.0);

fault := isFaultCondition;
normalMode := NOT isFirstScan AND NOT isFaultCondition AND NOT resetRising AND NOT modeChanged;

IF isFirstScan THEN
    flowSP := manualFlowSP;
    valveCommand := manualValve;
    accT := 0.0;
    accF := 0.0;
    isFirstScan := FALSE;

ELSIF resetRising THEN
    flowSP := manualFlowSP;
    valveCommand := manualValve;
    accT := 0.0;
    accF := 0.0;

ELSIF isFaultCondition THEN
    flowSP := manualFlowSP;
    valveCommand := manualValve;
    accT := 0.0;
    accF := 0.0;

ELSIF modeChanged THEN
    IF mode = 2 THEN
        flowSP := prevFlowSP;
        valveCommand := prevValveCommand;
    ELSE
        flowSP := manualFlowSP;
        valveCommand := prevValveCommand;
    END_IF

ELSIF normalMode THEN
    IF mode = 0 THEN
        flowSP := manualFlowSP;
        valveCommand := manualValve;
    ELSE
        trialT := accT + 0.2 * eT * scanSeconds;
        flowSP := 1.0 * eT + trialT;
        IF flowSP > 50.0 THEN
            flowSP := 50.0;
        ELSIF flowSP < 0.0 THEN
            flowSP := 0.0;
        END_IF;
        accT := flowSP - 1.0 * eT;

        eF := flowSP - flowPV;
        trialF := accF + 0.5 * eF * scanSeconds;
        valveCommand := 2.0 * eF + trialF;
        IF valveCommand > 100.0 THEN
            valveCommand := 100.0;
        ELSIF valveCommand < 0.0 THEN
            valveCommand := 0.0;
        END_IF;
        accF := valveCommand - 2.0 * eF;

        IF mode = 0 THEN
            flowSP := manualFlowSP;
            valveCommand := manualValve;
        END_IF;
    END_IF;

ELSE
    flowSP := prevFlowSP;
    valveCommand := prevValveCommand;
END_IF;

prevResetBtn := resetBtn;
prevMode := mode;
prevFlowSP := flowSP;
prevValveCommand := valveCommand;

END_FUNCTION_BLOCK
